// Minimal local PDF 1.4 writer for trusted RGB JPEG pages generated by our canvas.
// ISO 32000-1 sections 7.5 (file structure) and 8.9 (image XObjects).
// No parser, active content, remote resources, or untrusted PDF input is involved.
export class RasterPdf {
  private offset: number = 0;
  private offsets: number[] = [0];
  private index: number = 0;
  private closed: boolean = false;
  private readonly count: number;
  private readonly output: (data: Uint8Array) => void;
  constructor(count: number, output: (data: Uint8Array) => void) {
    if (!Number.isInteger(count) || count < 1 || count > 100) throw new Error('PDF 页数无效。');
    this.count = count; this.output = output;
    this.text('%PDF-1.4\n'); this.bytes(new Uint8Array([37, 226, 227, 207, 211, 10]));
    this.object(1, '<< /Type /Catalog /Pages 2 0 R >>');
    const children: string[] = [];
    for (let index = 0; index < count; index++) children.push((3 + index * 3) + ' 0 R');
    this.object(2, '<< /Type /Pages /Count ' + count + ' /Kids [' + children.join(' ') + '] >>');
  }
  private bytes(data: Uint8Array): void { this.output(data); this.offset += data.length; }
  private text(value: string): void {
    const data = new Uint8Array(value.length);
    for (let index = 0; index < value.length; index++) data[index] = value.charCodeAt(index);
    this.bytes(data);
  }
  private start(id: number): void { this.offsets[id] = this.offset; this.text(id + ' 0 obj\n'); }
  private object(id: number, value: string): void { this.start(id); this.text(value + '\nendobj\n'); }
  page(jpeg: Uint8Array, width: number, height: number): void {
    if (this.closed || this.index >= this.count || jpeg.length < 4 || jpeg[0] !== 255 || jpeg[1] !== 216 || jpeg[jpeg.length - 2] !== 255 || jpeg[jpeg.length - 1] !== 217) throw new Error('PDF 页面图片无效。');
    if (!Number.isInteger(width) || !Number.isInteger(height) || width < 1 || height < 1 || width * height > 40000000) throw new Error('PDF 图片尺寸无效。');
    const id = 3 + this.index * 3;
    this.object(id, '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /PageImage ' + (id + 1) + ' 0 R >> >> /Contents ' + (id + 2) + ' 0 R >>');
    this.start(id + 1); this.text('<< /Type /XObject /Subtype /Image /Width ' + width + ' /Height ' + height + ' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ' + jpeg.length + ' >>\nstream\n');
    this.bytes(jpeg); this.text('\nendstream\nendobj\n');
    const content = 'q\n595 0 0 842 0 0 cm\n/PageImage Do\nQ\n';
    this.object(id + 2, '<< /Length ' + content.length + ' >>\nstream\n' + content + 'endstream'); this.index++;
  }
  finish(): void {
    if (this.closed || this.index !== this.count) throw new Error('PDF 页面尚未完成。');
    const start = this.offset, size = this.count * 3 + 3;
    this.text('xref\n0 ' + size + '\n0000000000 65535 f \n');
    for (let id = 1; id < size; id++) this.text(this.offsets[id].toString().padStart(10, '0') + ' 00000 n \n');
    this.text('trailer\n<< /Size ' + size + ' /Root 1 0 R >>\nstartxref\n' + start + '\n%%EOF\n'); this.closed = true;
  }
}
